import{_ as e,o as s,c as a,ah as r}from"./chunks/framework.BMM80GXQ.js";const o="/assets/1.0/images/attributes/createAttribute.png",i="/assets/1.0/images/attributes/general.png",n="/assets/1.0/images/attributes/label.png",p="/assets/1.0/images/attributes/validation.png",l="/assets/1.0/images/attributes/configuration.png",g="/assets/1.0/images/attributes/output.png",u="/assets/1.0/images/attributes/family.png",c="/assets/1.0/images/attributes/product.png",d="/assets/1.0/images/attributes/text.png",m="/assets/1.0/images/attributes/textarea.png",h="/assets/1.0/images/attributes/boolean.png",b="/assets/1.0/images/attributes/select.png",f="/assets/1.0/images/attributes/multiselect.png",_="/assets/1.0/images/attributes/datetime.png",y="/assets/1.0/images/attributes/date.png",A="/assets/1.0/images/attributes/gallery.png",w="/assets/1.0/images/attributes/image.png",P="/assets/1.0/images/attributes/file.png",k="/assets/1.0/images/attributes/checkbox.png",T="/assets/1.0/images/attributes/price.png",U=JSON.parse('{"title":"Product Attribute","description":"","frontmatter":{},"headers":[],"relativePath":"1.0/attribute/product-attribute.md","filePath":"1.0/attribute/product-attribute.md","lastUpdated":1775051911000}'),v={name:"1.0/attribute/product-attribute.md"};function x(S,t,G,C,I,q){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="product-attribute" tabindex="-1">Product Attribute <a class="header-anchor" href="#product-attribute" aria-label="Permalink to &quot;Product Attribute&quot;">​</a></h1><p>An Attribute is a specification or characteristic of a product for example Color, Size, and Pattern an attribute of a T-Shirt.</p><p>You can as create many attributes for a single product. Product Attribute plays a major factor.</p><h3 id="how-to-create-a-product-attribute-in-unopim" tabindex="-1">How to Create a Product Attribute in UnoPim <a class="header-anchor" href="#how-to-create-a-product-attribute-in-unopim" aria-label="Permalink to &quot;How to Create a Product Attribute in UnoPim&quot;">​</a></h3><p>To Create UnoPim Attributes, open the Admin Panel and then follow the below steps.</p><h3 id="add-attributes" tabindex="-1">Add Attributes <a class="header-anchor" href="#add-attributes" aria-label="Permalink to &quot;Add Attributes&quot;">​</a></h3><p><strong>Step-1</strong> Click on <strong>Catalog</strong> &gt;&gt; <strong>Attributes</strong> &gt;&gt; <strong>Create Attributes</strong> as shown in the below image.</p><p><img src="'+o+'" alt="Attribute"></p><p><strong>Step-2</strong> Now enter the <strong>Code</strong> and <strong>Data Type</strong> inside the general section.</p><p><img src="'+i+'" alt="General"></p><p><strong>Note -</strong> The <strong>Is Unique</strong> Validation is only available for Type - <strong>Text, Datetime &amp; Date</strong></p><p><strong>Step-3</strong> Enter the Label of your Attribute as shown in the below image.</p><p><img src="'+n+'" alt="Label"></p><p><strong>Step-4</strong> Select the Validation if you want to make your Attribute as a required field or Unique.</p><p><strong>Note -</strong> The <strong>Is Unique</strong> Validation is only available for Type - <strong>Text, Datetime &amp; Date</strong></p><p><img src="'+p+'" alt="Validation"></p><p><strong>Step-5</strong> Select the field if you want to make the Attribute value as per the locale and value as per the channel.</p><p><img src="'+l+'" alt="Configuration"></p><p>Now, click on <strong>Save Attribute</strong> button and then the attribute is created successfully in the Datagrid.</p><p><img src="'+g+'" alt="Output"></p><p>Now <strong>Save the Attribute</strong> and then go the the Attribute Family from <strong>Catalog &gt;&gt; Attribute Families</strong> and assign it from the unassigned attribute by drag and drop at your desired place as shown in the below image.</p><p><img src="'+u+'" alt="Family"></p><p>Now, <strong>Save Attribute Family</strong> and check the output while creating products on the product edit page as shown in the below image.</p><p><img src="'+c+'" alt="Product"></p><h3 id="a-visual-breakdown-of-unopim-12-product-data-types" tabindex="-1">A Visual Breakdown of UnoPim 12 Product Data Types <a class="header-anchor" href="#a-visual-breakdown-of-unopim-12-product-data-types" aria-label="Permalink to &quot;A Visual Breakdown of UnoPim 12 Product Data Types&quot;">​</a></h3><p><strong>1) Text</strong> - A field that allows the user to enter a single line of text. It is typically used for short inputs like names, email addresses, or search queries.</p><p><img src="'+d+'" alt="General"></p><p><strong>2) Textarea</strong> - A field that provides a larger area for users to input multi-line text. It’s useful for longer responses or comments, such as descriptions or messages.</p><p>Additionally, you can Enable/Disable the Wysiwyg Editor.</p><p><img src="'+m+'" alt="General"></p><p><strong>3) Boolean</strong> - Represents a true or false value. It&#39;s often used in forms to capture yes/no or on/off selections.</p><p><img src="'+h+'" alt="General"></p><p><strong>4) Select</strong> - A dropdown menu that allows users to choose one option from a list. It’s useful for making selections where only one option should be chosen from a predefined set of options.</p><p><img src="'+b+'" alt="General"></p><p><strong>5) Multiselect</strong> - Similar to a select field but allows users to choose multiple options from a list. It’s useful when multiple selections are valid and necessary.</p><p><img src="'+f+'" alt="General"></p><p><strong>6) Datetime</strong> - A field that allows users to select a specific date and time. It’s often used for scheduling or timestamping events.</p><p><img src="'+_+'" alt="General"></p><p><strong>7) Date</strong> - A field that allows users to select or input a date only (without time). It’s used for choosing a specific day in forms and calendars.</p><p><img src="'+y+'" alt="General"></p><p><strong>8) Gallery</strong> - A Gallery attribute that allows managing and displaying multiple images per product, enhancing the product media experience.</p><ol><li>The media attribute provides the ability to edit gallery images without changing their position.</li></ol><ol start="2"><li><p>Change the image position by dragging and dropping the gallery images.</p><p><img src="'+A+'" alt="General"></p></li></ol><p><strong>9) Image</strong> - A field for uploading or displaying image. Users can either upload an image file or view an image that’s already been uploaded.</p><p><img src="'+w+'" alt="General"></p><p><strong>10) File</strong> - A field that allows users to upload files. It can accept various file types, such as documents, images, or other file formats.</p><p><img src="'+P+'" alt="General"></p><p><strong>11) Checkbox</strong> - A small box that can be checked or unchecked. It’s used for binary choices, where a user can select or deselect an option, often used for agreements or preferences.</p><p><img src="'+k+'" alt="General"></p><p><strong>12) Price</strong>- This input type is used to create price fields that are in addition to the predefined attributes: Prices.</p><p><img src="'+T+'" alt="General"></p><p>By following the above steps, you can easily create a <strong>Product Attribute</strong> in UnoPim.</p>',52)])])}const N=e(v,[["render",x]]);export{U as __pageData,N as default};
